parameters.jsCode:
/**
 * Normaliza o lead para o envio.
 *
 * Aceita dois formatos, para o gatilho poder ser trocado sem refazer o fluxo:
 *  · Database Webhook do Supabase → { type, table, record: { ... } }
 *  · Chamada direta do CRM         → { nome, empresa, telefone, ... }
 *
 * Em Code node NÃO se usa {{ }}: o acesso é JavaScript direto.
 */
const body = $json.body ?? {};
const lead = body.record ?? body;

const texto = (v) => (typeof v === 'string' ? v.trim() : '');

const nome = texto(lead.nome);
const empresa = texto(lead.empresa);
const email = texto(lead.email);

/* Primeiro nome: numa mensagem de WhatsApp, "Olá, Mariana" soa melhor
   do que o nome completo. */
const primeiroNome = nome.split(/\s+/)[0] || 'tudo bem';

/* Telefone para o formato E.164 sem o "+", que é o que a Graph API espera.
   Entrada típica do formulário: "(11) 9 8812-4409". */
const digitos = texto(lead.telefone).replace(/\D/g, '');
let numero = digitos;
if (numero.startsWith('0')) numero = numero.replace(/^0+/, '');
if (!numero.startsWith('55')) numero = '55' + numero;

/* 55 + DDD (2) + assinante (8 ou 9) → 12 ou 13 dígitos. Fora disso, não
   dá para afirmar que é um número de WhatsApp válido. */
const valido = numero.length === 12 || numero.length === 13;

return [{
  json: {
    id: lead.id ?? null,
    nome,
    primeiroNome,
    empresa: empresa || 'sua empresa',
    email,
    telefoneOriginal: texto(lead.telefone),
    telefone: numero,
    valido,
    motivo: valido ? null : 'Telefone fora do padrão E.164 brasileiro (12 ou 13 dígitos com o 55).',
  },
}];

parameters.jsonBody:
={{ JSON.stringify({
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to: $json.telefone,
  type: 'template',
  template: {
    name: 'diagnostico_recebido',
    language: { code: 'pt_BR' },
    components: [
      {
        type: 'body',
        parameters: [
          { type: 'text', text: $json.primeiroNome },
          { type: 'text', text: $json.empresa }
        ]
      }
    ]
  }
}) }}
